function evolveV6(){S.players.filter(p=>p.status!="Transfer oldu").forEach(p=>{let d=Math.max(0,24-p.age)*.03+((p.form||70)-70)*.012+Math.min(1,(p.minutes||0)/900)*.3-Math.max(0,p.age-29)*.07;p.growth=(p.growth||0)+d;if(p.growth>=1&&p.overall<p.potential){p.overall++;p.growth-=1;pushInbox("Teknik Ekip",`${p.name} gelişti`,`${p.name} artık OVR ${p.overall}.`,"player")}if(p.growth<=-1&&p.age>=30){p.overall--;p.growth+=1}p.happiness=Math.max(20,Math.min(100,(p.happiness??70)+((p.morale||70)-70)*.02))})}
