function completeOfficeDay(){S.history.push("Teknik ekip toplantısını tamamladın. Maç planı artık hafta boyunca güncellenebilir.");save();advance()}
function showWorld(){modal=null;let table=[...S.table].sort((a,b)=>b.pts-a.pts||(b.gf-b.ga)-(a.gf-a.ga)),leader=table[0],formTeam=Object.entries(S.form).sort((a,b)=>b[1].slice(-5).filter(x=>x=="G").length-a[1].slice(-5).filter(x=>x=="G").length)[0];$("#app").innerHTML=`${header()}<button class=secondary onclick=render()>‹ Geri</button><h1>Kupa & Gündem</h1><div class=card><h2>Türkiye Kupası</h2><p>${S.v6.cup.alive?S.v6.cup.round:"Elendi"} • ${S.v6.cup.wins} tur galibiyeti</p></div><div class="card story"><h2>📰 Haftanın Manşetleri</h2><p>${leader.n}, ${leader.pts} puanla zirvede.</p><p>${formTeam?formTeam[0]:"Lig"} son haftalarda dikkat çekiyor.</p><p>${currentOpponent()[0]}: ${currentOpponent()[9]}.</p></div><div class=card><h3>${escapeHTML(managedClubName())}</h3>${S.players.slice().sort((a,b)=>b.goals-a.goals).slice(0,5).map(p=>`<div class="row between player"><span>${p.name}</span><span>⚽ ${p.goals} • ${p.minutes}'</span></div>`).join("")}</div>`;decorateMainScreen("league");}
function showLeague(){modal=null;ensureLeague();let t=[...S.table].sort((a,b)=>b.pts-a.pts||(b.gf-b.ga)-(a.gf-a.ga)||b.gf-a.gf),round=Math.max(0,S.fixture-1),games=S.leagueSchedule[round]||[];$("#app").innerHTML=`${header()}<button class=secondary onclick=render()>‹ Geri</button><h1>Lig Tablosu</h1><div class=card><div class="leaguehead"><span>Takım</span><span>O</span><span>AV</span><span>P</span></div>${t.map((x,i)=>`<div class=leaguerow><span>${i+1}. ${x.n}${formDots(x.n)}</span><span>${x.p}</span><span>${x.gf-x.ga}</span><b>${x.pts}</b></div>`).join("")}</div><div class=card><h3>${round+1}. Hafta Sonuçları</h3>${games.map(g=>`<div class="row between player"><span>${g.home} – ${g.away}</span><b>${g.played?g.hg+"–"+g.ag:"-"}</b></div>`).join("")}</div>`;decorateMainScreen("league");}
function showSettings(){modal=null;modal="settings";$("#app").innerHTML=`${header()}<button class=secondary onclick="modal=null;render()">‹ Kariyere dön</button><h1>Ayarlar</h1><div class=card><h2>Kariyer</h2><p class=muted>Mevcut kariyer, fikstür, kadro, sonuçlar, oyuncu ilişkileri ve tüm ilerleme bu cihazdan silinir.</p><button class=warn onclick="confirmResetCareer()">Kariyeri Sıfırla</button><div class=build-version>ManagerStory • V7.4.0 • MatchEngine V2</div><button class=secondary onclick="exportCareer()">Kariyer Yedeği İndir</button><label class="importlabel secondary">Kariyer Yedeği Yükle<input type=file accept="application/json,.json" onchange="importCareer(this.files[0])"></label></div>`;decorateMainScreen("home");}
function confirmResetCareer(){let ok=confirm("Kariyeri sıfırlamak istediğine emin misin?\\n\\nTüm ilerleme kalıcı olarak silinecek.");if(!ok)return;localStorage.removeItem("msv4");loadError="";S=null;M=null;modal=null;window.OUT=null;render()}
function contextCards(e){if(e.kind=="matchday"){let r=currentOpponent();return `<div class=card><b>Rakip Analizi</b><p>${analysis(r)}</p><span class=pill>${S.plan.mentality}</span><span class=pill>${S.plan.press} pres</span><span class=pill>Aras: ${S.plan.aras}</span></div>`}if(e.kind=="transfer"){let p=S.players.find(x=>x.id==e.player);return `<div class=card><b>${p.name}</b><p>OVR ${p.overall} • ${p.age} yaş • Değer ${money(p.value)} • Moral ${p.morale}</p></div>`}if(e.kind=="player"){let p=S.players.find(x=>x.id==e.player);return `<div class=card><b>Oyuncu ilişkisi ${p.relation}/100</b><p>Moral ${p.morale} • Form ${p.form} • Potansiyel ${p.potential}</p></div>`}if(e.kind=="office"){let r=currentOpponent();return `<div class=card><small>BU HAFTAKİ RAKİP</small><h3>${r[0]}</h3><p>${analysis(r)}</p><span class=pill>${S.plan.mentality}</span><span class=pill>${S.plan.press} pres</span></div>`}return ""}
function analysis(r){let base=r[9]+`. Hücum ${r[3]}, orta saha ${r[4]}, savunma ${r[5]}, kaleci ${r[6]}.`;if(r[2]=="high")return base+" Savunma çizgisi önde; hızlı koşular arkadaki alanı tehdit edebilir.";if(r[2]=="deep")return base+" Derin blok kuruyor; fiziksel santrfor ve ikinci koşular değerli olabilir.";if(r[2]=="physical")return base+" İkili mücadele ve duran toplarda dikkatli olmak gerekiyor.";return base+" Orta saha üstünlüğü maçın yönünü belirleyebilir."}
function choose(x){let e=S.event;if(e?.kind==='meeting'&&x.startsWith('meeting:')){const [,id,response]=x.split(':');resolvePlayerMeeting(Number(id),response);return}
 if(x.startsWith("dynPromise:")){let id=+x.split(":")[1],p=S.players.find(q=>q.id==id);p.morale+=5;p.relation+=3;S.promises.push({type:"minutes",player:id,due:S.week+3,atMinutes:p.minutes});S.history.push(`${p.name}'a süre sözü verdin.`);advance();return}
 if(x.startsWith("dynDemand:")){let id=+x.split(":")[1],p=S.players.find(q=>q.id==id);p.form+=2;p.morale-=2;S.history.push(`${p.name}'dan formasını kazanmasını istedin.`);advance();return}
 if(x.startsWith("dynCalm:")){let id=+x.split(":")[1],p=S.players.find(q=>q.id==id);p.morale+=1;S.history.push(`${p.name}'a rotasyondaki rolünü anlattın.`);advance();return}
 if(x.startsWith("dynRest:")){let id=+x.split(":")[1],p=S.players.find(q=>q.id==id);p.fitness=Math.min(100,p.fitness+12);S.history.push(`${p.name} özel olarak dinlendirildi.`);advance();return}
 if(x.startsWith("dynNormal:")){let id=+x.split(":")[1],p=S.players.find(q=>q.id==id);p.form+=1;S.history.push(`${p.name} normal programa devam etti.`);advance();return}
 if(x=="dynCaptain"){S.players.forEach(p=>p.morale=Math.min(100,p.morale+2));S.history.push("Burak soyunma odasında liderliği üstlendi.");advance();return}
 if(x=="dynManager"){S.players.forEach(p=>p.relation=Math.min(100,p.relation+1));S.history.push("Takımla doğrudan sen konuştun.");advance();return}
 if(x=="ambitious"){S.board+=2;S.history.push("Yönetime üst sıraları hedeflediğini söyledin.")}
 if(x=="calm"){S.history.push("Yönetime sabırlı bir sezon planı sundun.")}
 if(x=="youth"){S.board+=1;S.promises.push({type:"youth",due:S.week+5});S.history.push("Yönetime genç oyunculara fırsat sözü verdin.")}
 if(x=="tactics"){S.players.forEach(p=>p.form=Math.min(100,p.form+1));S.history.push("Haftaya taktik antrenmanıyla başladın.");advance();return}
 if(x=="fitness"){S.players.forEach(p=>{p.fitness=Math.min(100,p.fitness+4);p.morale=Math.max(40,p.morale-1)});S.history.push("Takım yoğun fizik çalıştı.");advance();return}
 if(x=="meeting"){S.players.forEach(p=>p.morale=Math.min(100,p.morale+2));S.history.push("Takımla kapalı bir toplantı yaptın.");advance();return}
 if(x=="arasCenter"){S.plan.aras="Merkeze yakın";S.players[11].relation+=5;S.players[11].morale+=4;S.history.push("Aras'a merkezde daha fazla sorumluluk sözü verdin.");advance();return}
 if(x=="arasFree"){S.players[11].relation+=4;S.history.push("Aras'a serbestlik ve güven verdin.");advance();return}
 if(x=="earn"){S.players[11].relation-=2;S.players[11].form+=2;S.history.push("Aras'tan formasını sahada kazanmasını istedin.");advance();return}
 if(x=="counter"){e.text="Kuzey Liman ₺11.5M'ye çıktı. Sportif direktör son kararını bekliyor.";e.choices=[["₺11.5M kabul et.","accept115"],["₺13M'de ısrar et.","insist"],["Masadan kalk.","reject"]];S.history.push("Mensah için ₺13M karşı teklif yaptın.");save();render();return}
 if(x=="accept"||x=="accept115"){let fee=x=="accept"?9.5e6:11.5e6,oldPos=S.positions[12]||SLOT_POS.ST;S.budget+=fee;S.history.push(`Mensah ${money(fee)} karşılığında Kuzey Liman'a satıldı.`);S.players[12].status="Transfer oldu";S.xi=S.xi.filter(i=>i!=12);delete S.positions[12];if(!S.xi.includes(13)){S.xi.push(13);S.positions[13]=[...oldPos]}S.clubMood.chairman=`Mensah satışı sonrası bütçe ${money(S.budget)}`;S.clubMood.dressing="Mensah'ın ayrılığı konuşuluyor";pushInbox("Başkan","Mensah transferi",`Satış tamamlandı. ${money(fee)} gelir elde ettik. Yerine doğru profili bulmanı bekliyorum.`,"board");pushInbox("Burak ©","Soyunma odası","Mensah'ın gidişi konuşuluyor hocam. Yeni gelecek oyuncunun takıma hızlı uyum sağlaması önemli.","player");normalizeFormation();advance();return}
 if(x=="insist"){S.history.push("Kuzey Liman ₺13M talebini kabul etmedi. Mensah takımda kaldı.");S.players[12].morale-=3;advance();return}
 if(x=="reject"){S.players[12].morale-=2;S.history.push("Mensah için gelen teklifi reddettin.");advance();return}
 if(x=="analysis"){alert(analysis(currentOpponent()));return}
 if(x=="squad"){modal="squad";render();return}
 if(x=="plan"){modal="plan";render();return}
 if(x=="pressCalm"){S.players.forEach(p=>p.morale=Math.min(100,p.morale+1));S.history.push("Basına kontrollü bir mesaj verdin.");advance();return}
 if(x=="pressBold"){S.fans+=2;S.history.push("Basına cesur ve iddialı konuştun.");advance();return}
 if(x=="pressNeutral"){S.history.push("Basına ölçülü ve kapalı bir mesaj verdin.");pushInbox("Basın Sorumlusu","Basın toplantısı","Mesajın kontrollü bulundu.");advance();return}
 if(x=="pressTactical"){S.players.forEach(p=>p.form=Math.min(100,p.form+1));S.history.push("Basında taktik ayrıntılara işaret ettin.");advance();return}
 if(x=="pressTrust"){S.players.forEach(p=>p.morale=Math.min(100,p.morale+2));S.clubMood.dressing="Hocanın güvenini hissediyor";S.history.push("Oyuncularına kamuoyu önünde güvendin.");advance();return}
 if(x=="pressDemand"){S.players.forEach(p=>{p.form=Math.min(100,p.form+1);p.morale=Math.max(45,p.morale-1)});S.history.push("Basın önünde takımdan daha fazlasını istedin.");advance();return}
 if(x=="formation"){modal="formation";render();return}
 if(x=="match"){startMatch();return}
 if(x=="rest"){S.players.forEach(p=>p.fitness=Math.min(100,p.fitness+12));S.history.push("Maçın ertesi günü takımı dinlendirdin.");advance();return}
 if(x=="review"){S.players.forEach(p=>p.form=Math.min(100,p.form+1));S.history.push("Teknik ekiple maç analizini tamamladın.");advance();return}
 save();advance()}
