function matchField(){let cards=M.active.map(id=>{let p=S.players.find(x=>x.id==id),q=S.positions[id]||[50,50];return `<div class=pc style="left:${q[0]}%;top:${q[1]}%"><b>${p.name}</b><br>${p.pos} ${Math.round(p.fitness)}%</div>`}).join("");$("#app").innerHTML=`<button class=secondary onclick=render()>‹ Maça dön</button><h1>Sahadaki 11</h1><div class=pitch>${cards}</div>`}
function teamProfile(name){if(name=="Anadolu Hisarı")return {atk:72,mid:72,def:70,gk:70,home:3};let r=OPP.find(x=>x[0]==name);return {atk:r[3],mid:r[4],def:r[5],gk:r[6],home:3}}
function poisson(lambda,rnd){let L=Math.exp(-lambda),k=0,p=1;do{k++;p*=rnd()}while(p>L&&k<8);return k-1}
function simAIGame(g,week,index){let h=teamProfile(g.home),a=teamProfile(g.away),rnd=R(41000+week*211+index*17),hf=(S.form[g.home]||[]).slice(-5).reduce((x,y)=>x+(y=="G"?1:y=="M"?-.7:0),0),af=(S.form[g.away]||[]).slice(-5).reduce((x,y)=>x+(y=="G"?1:y=="M"?-.7:0),0);let lh=Math.max(.35,1.22+(h.atk+a.mid-h.def*.15-a.def*.55)/55+h.home/20+hf*.04),la=Math.max(.3,1.08+(a.atk+h.mid-a.def*.15-h.def*.55)/55+af*.04);g.hg=Math.min(6,poisson(lh,rnd));g.ag=Math.min(6,poisson(la,rnd));g.played=true;applyTableGame(g);recordForm(g)}
function applyTableGame(g){let h=S.table.find(x=>x.n==g.home),a=S.table.find(x=>x.n==g.away);if(!h||!a)return;h.p++;a.p++;h.gf+=g.hg;h.ga+=g.ag;a.gf+=g.ag;a.ga+=g.hg;if(g.hg>g.ag)h.pts+=3;else if(g.ag>g.hg)a.pts+=3;else{h.pts++;a.pts++}}
function recordForm(g){let hf=g.hg>g.ag?"G":g.hg==g.ag?"B":"M",af=g.ag>g.hg?"G":g.ag==g.hg?"B":"M";S.form[g.home].push(hf);S.form[g.away].push(af)}
function simulateRoundOthers(){ensureLeague();let games=S.leagueSchedule[S.fixture];games.forEach((g,i)=>{if(!g.played&&g.home!="Anadolu Hisarı"&&g.away!="Anadolu Hisarı")simAIGame(g,S.fixture,i)})}
function pressQuestion(ug,og){return makeV71PostPress(ug,og)}
function finishMatch(){if(!M||!M.finished||livePresentationPending()||currentFixture().game.played||M.resultCommitted)return;M.resultCommitted=true;const completedMatch=M;let ug=M.userHome?M.hg:M.ag,og=M.userHome?M.ag:M.hg,game=currentFixture().game;game.hg=M.hg;game.ag=M.ag;game.played=true;applyTableGame(game);recordForm(game);simulateRoundOthers();evolveOpponentSquads(S.fixture);S.results.push({home:M.home,away:M.away,hg:M.hg,ag:M.ag,week:S.fixture+1});S.board=Math.max(20,Math.min(100,S.board+(ug>og?3:ug==og?0:-2)));S.fans=Math.max(20,Math.min(100,S.fans+(ug>og?3:ug==og?0:-2)));let result=ug>og?"galibiyet":ug==og?"beraberlik":"mağlubiyet";S.history.push(`${M.home} ${M.hg}-${M.ag} ${M.away} • ${result}.`);S.v6.academyCounter++;evolveV6();if(S.v6.academyCounter>=3+(S.fixture%2))refreshAcademy();if(S.results.length>=3){let recent=S.results.slice(-4),gf=recent.reduce((n,r)=>n+(r.home=="Anadolu Hisarı"?r.hg:r.ag),0),ga=recent.reduce((n,r)=>n+(r.home=="Anadolu Hisarı"?r.ag:r.hg),0),wins=recent.filter(r=>(r.home=="Anadolu Hisarı"?r.hg:r.ag)>(r.home=="Anadolu Hisarı"?r.ag:r.hg)).length;if(wins<=1){let msg=gf<4?`Son ${recent.length} maçta ${gf} gol ürettik. Hücum bağlantıları ve ceza sahası koşuları yetersiz kaldı.`:ga>gf?`Son ${recent.length} maçta ${ga} gol yedik. Özellikle maçların ikinci bölümünde savunma dengemiz bozuluyor.`:`Son ${recent.length} maçta sonuç almakta zorlandık. Orta saha ile hücum arasındaki mesafe açılıyor.`;pushInbox("Yardımcı Antrenör","Son Maçlar Analizi",msg+" Bir sonraki teknik ekip toplantısında planı buna göre gözden geçirelim.","player")}}let pq=pressQuestion(ug,og);S.results[S.results.length-1].matchSummary=matchSummary(completedMatch);S.v71.lastMatch=matchSummary(completedMatch);settlePlayerPromises();M=null;modal=null;delete S.activeMatchV71;S.fixture=Math.min(33,S.fixture+1);S.event={kind:"postpress",title:"🎤 Maç Sonu Röportajı",speaker:"Muhabir",text:pq[0],choices:pq[1],questionId:pq[2],category:pq[3]};save();render()}
function choosePost(x){ }
const oldChoose=choose;choose=function(x){if(S.event&&["press","postpress","office"].includes(S.event.kind))applyConversationEffect(S.event.kind,x);if(S.event&&S.event.kind=="postpress"){if(x=="postTeam"){S.players.forEach(p=>p.morale=Math.min(100,p.morale+2));S.fans+=1;S.history.push("Maç sonunda oyuncularını övdün.")}if(x=="postMe"){S.players.forEach(p=>p.relation=Math.min(100,p.relation+1));S.board-=1;S.history.push("Sonucun sorumluluğunu üstlendin.")}if(x==="postTactical"){S.players.filter(p=>S.xi.includes(p.id)).forEach(p=>p.form=Math.min(100,p.form+1));S.history.push("Maçın taktik yönünü açıkladın.")}if(x=="postDemand"){S.board+=1;S.players.forEach(p=>p.morale=Math.max(35,p.morale-1));S.history.push("Takımdan daha fazlasını istedin.")}save();advance();return}return oldChoose(x)}
render();
